migrations.content:
CREATE TABLE IF NOT EXISTS columns (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE ON UPDATE CASCADE,
  title text NOT NULL,
  position int NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_columns_session_position ON columns (session_id, position);

CREATE TRIGGER set_timestamp_columns
BEFORE UPDATE ON columns
FOR EACH ROW
EXECUTE FUNCTION set_timestamp();

CREATE TABLE IF NOT EXISTS clusters (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE ON UPDATE CASCADE,
  column_id uuid NOT NULL REFERENCES columns(id) ON DELETE CASCADE ON UPDATE CASCADE,
  title text NOT NULL,
  position int NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_clusters_column_position ON clusters (column_id, position);
CREATE INDEX IF NOT EXISTS idx_clusters_session ON clusters (session_id);

CREATE TRIGGER set_timestamp_clusters
BEFORE UPDATE ON clusters
FOR EACH ROW
EXECUTE FUNCTION set_timestamp();

CREATE TABLE IF NOT EXISTS cards (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE ON UPDATE CASCADE,
  column_id uuid NOT NULL REFERENCES columns(id) ON DELETE CASCADE ON UPDATE CASCADE,
  cluster_id uuid REFERENCES clusters(id) ON DELETE SET NULL ON UPDATE CASCADE,
  content text NOT NULL,
  author_name text,
  position int NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_cards_column_position ON cards (column_id, position);
CREATE INDEX IF NOT EXISTS idx_cards_cluster ON cards (cluster_id);
CREATE INDEX IF NOT EXISTS idx_cards_session ON cards (session_id);

CREATE TRIGGER set_timestamp_cards
BEFORE UPDATE ON cards
FOR EACH ROW
EXECUTE FUNCTION set_timestamp();

CREATE TABLE IF NOT EXISTS votes (
  id bigserial PRIMARY KEY,
  session_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE ON UPDATE CASCADE,
  voter_id uuid NOT NULL,
  target_type text NOT NULL CHECK (target_type IN ('card','cluster')),
  target_id uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (voter_id, session_id, target_type, target_id)
);

CREATE INDEX IF NOT EXISTS idx_votes_session_voter ON votes (session_id, voter_id);
CREATE INDEX IF NOT EXISTS idx_votes_target ON votes (target_type, target_id);

CREATE OR REPLACE FUNCTION set_timestamp()
RETURNS trigger AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- The trigger is attached in each table migration above.
